import datetime, json, re
HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MON = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
ONE = datetime.timedelta(days=1)
def isbd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def nextbd(d):
    d = d + ONE
    while not isbd(d):
        d = d + ONE
    return d
def nth_bd(d, n):
    for _ in range(n):
        d = nextbd(d)
    return d
def words(d):
    return WD[d.weekday()] + ' ' + str(d.day) + ' ' + MON[d.month - 1]
def full(d):
    return words(d) + ' (' + d.isoformat() + ')'
def money(x):
    return '{:,.2f}'.format(float(x))
def last_bd_of_week(d):
    sun = d + datetime.timedelta(days=6 - d.weekday())
    x = sun
    while not isbd(x):
        x = x - ONE
    return x
def get_products():
    for k in ('products', 'load_account_response.data.products', 'get_account_response.data.products'):
        v = vars.get(k)
        if isinstance(v, str):
            try:
                v = json.loads(v)
            except Exception:
                v = None
        if isinstance(v, list) and v:
            return v
        if isinstance(v, dict) and v:
            return [v]
    items = dict()
    for k in list(vars.keys()):
        m = re.search(r'products\.(\d+)\.(\w+)$', str(k))
        if m:
            items.setdefault(int(m.group(1)), dict())[m.group(2)] = vars.get(k)
    return [items[i] for i in sorted(items)]
try:
    raw = str(vars.get('now') or '')
    try:
        now = datetime.datetime.strptime(raw[:16], '%Y-%m-%dT%H:%M')
    except Exception:
        now = datetime.datetime.strptime(raw[:10], '%Y-%m-%d')
    today = now.date()
    vars['today_iso'] = today.isoformat()
    vars['today_words'] = full(today)
    vars['now_time'] = now.strftime('%H:%M')
    # callback window
    nb = nextbd(today)
    vars['cb_next_iso'] = nb.isoformat()
    earliest = now + datetime.timedelta(minutes=1)
    e = max('10:00', earliest.strftime('%H:%M'))
    if earliest.date() == today and e <= '19:00':
        vars['cb_today_ok'] = 'yes'
        vars['cb_today_earliest'] = e
        vars['callback_text'] = ('Allowed callback slots: today ' + full(today) + ' from ' + e + ' to 19:00, or ' + full(nb) + ' from 10:00 to 19:00. Nothing else is allowed.')
    else:
        vars['cb_today_ok'] = 'no'
        vars['cb_today_earliest'] = '99:99'
