        ptype = str(p.get('type') or '')
        last4 = str(p.get('card_last4') or '')
        if ptype == 'credit_card':
            pw = 'credit card ending ' + last4 if last4 else 'credit card'
            floor = p.get('minimum_payment')
            fname = 'minimum payment'
        elif ptype == 'car_loan':
            pw = 'car loan'
            floor = p.get('instalment_amount')
            fname = 'instalment amount'
        else:
            pw = 'personal loan'
            floor = p.get('instalment_amount')
            fname = 'instalment amount'
        past = float(p.get('past_due') or 0)
        floor = float(floor if floor not in (None, '') else past)
        dl = int(float(p.get('days_late') or 0))
        if dl <= 7:
            band = 'early'
            deadline = nth_bd(today, 12)
            attempts = 1
        else:
            band = 'late'
            deadline = nth_bd(today, 7)
            attempts = 2
        a1 = last_bd_of_week(today)
        if a1 <= today:
            a1 = last_bd_of_week(today + datetime.timedelta(days=7 - today.weekday()))
        allowed = []
        d = today
        while d <= deadline:
            if isbd(d):
                allowed.append(d.isoformat())
            d = d + ONE
        lines = []
        d = today
        end = deadline + datetime.timedelta(days=10)
        while d <= end:
            if d > deadline:
                st = 'AFTER the deadline: say the latest date you can record is ' + words(deadline) + ' and offer that date'
            elif isbd(d):
                st = 'OK, can be recorded'
            else:
                kind = 'holiday' if d.isoformat() in HOL else 'weekend'
                n = nextbd(d)
                if n > deadline:
